#!/bin/sh
# Generated by scripts/installers.ts. Edit install-template.sh, then regenerate.
set -eu
CHANNEL=stable
MODE=desktop
REPO=flexdinesh/tool-logger
fail() { printf 'tool-logger: %s\n' "$*" >&2; exit 1; }
has() { command -v "$1" >/dev/null 2>&1; }
[ -n "${HOME:-}" ] || fail 'HOME is not set'

case "$(uname -s)" in Linux) OS=linux ;; Darwin) OS=darwin ;; *) fail 'supported OS: Linux, macOS' ;; esac
case "$(uname -m)" in x86_64|amd64) ARCH=amd64 ;; aarch64|arm64) ARCH=arm64 ;; *) fail 'supported architecture: amd64, arm64' ;; esac
SELECTION=${1:-none}
[ "$MODE" != plugins ] || SELECTION=${1:-all}
[ "$#" -le 1 ] || fail 'usage: installer [codex|opencode|all]'
case "$SELECTION" in none|codex|opencode|all) ;; *) fail 'plugins: codex, opencode, all' ;; esac
if [ "$SELECTION" != none ]; then
  has node || fail 'Node.js 26 is required for plugins'
  [ "$(node -p 'process.versions.node.split(".")[0]')" = 26 ] || fail 'Node.js 26 is required for plugins'
  case "$SELECTION" in codex|all) has codex || fail 'Codex CLI is required' ;; esac
  case "$SELECTION" in opencode|all) has opencode2 || has opencode || fail 'OpenCode CLI is required' ;; esac
fi
if has sha256sum; then HASH=sha256sum
elif has shasum; then HASH=shasum
else fail 'sha256sum or shasum is required'; fi
digest() {
  if [ "$HASH" = sha256sum ]; then sha256sum "$1"; else shasum -a 256 "$1"; fi | cut -d ' ' -f 1
}
fetch() {
  if has curl; then curl -fsSL --retry 2 --connect-timeout 10 -o "$2" "$1"
  elif has wget; then wget -q -O "$2" "$1"
  else fail 'curl or wget is required'; fi
}
TMP=$(mktemp -d)
STAGED=
cleanup() { rm -rf "$TMP"; [ -z "$STAGED" ] || rm -rf "$STAGED"; }
trap cleanup EXIT
trap 'exit 130' INT TERM
if [ "$CHANNEL" = edge ]; then TAG=edge
elif [ -n "${TOOL_LOGGER_VERSION:-}" ]; then TAG=v${TOOL_LOGGER_VERSION#v}
else
  fetch "https://api.github.com/repos/$REPO/releases/latest" "$TMP/latest.json"
  TAG=$(sed -n 's/.*"tag_name": *"\([^"]*\)".*/\1/p' "$TMP/latest.json")
fi
case "$TAG" in edge|v[0-9]*) ;; *) fail 'could not determine release tag';; esac
BASE="https://github.com/$REPO/releases/download/$TAG"
fetch "$BASE/release.json" "$TMP/release.json"
VERSION=$(sed -n 's/^  "version": "\([^"]*\)",*$/\1/p' "$TMP/release.json")
MANIFEST_HASH=$(sed -n 's/^  "checksumsSha256": "\([a-f0-9]*\)",*$/\1/p' "$TMP/release.json")
case "$VERSION" in ''|*[!A-Za-z0-9.+-]*) fail 'invalid release version';; esac
[ "${#MANIFEST_HASH}" = 64 ] || fail 'invalid release checksum metadata'
if [ "$CHANNEL" = stable ]; then [ "$TAG" = "v$VERSION" ] || fail 'release tag/version mismatch'; fi
# Pin all downloads to this metadata revision. A concurrent edge update fails
# verification before installation, instead of mixing assets from two builds.
fetch "$BASE/checksums.txt" "$TMP/checksums.txt"
[ "$(digest "$TMP/checksums.txt")" = "$MANIFEST_HASH" ] || fail 'release changed during download; run installer again'
download() {
  asset=$1
  expected=$(awk -v name="$asset" '$2 == name { print $1 }' "$TMP/checksums.txt")
  [ "${#expected}" = 64 ] || fail "missing or duplicate checksum: $asset"
  fetch "$BASE/$asset" "$TMP/$asset"
  [ "$(digest "$TMP/$asset")" = "$expected" ] || fail "checksum mismatch: $asset"
}
extract_tar() {
  # Release archives contain regular files/directories only, except macOS app
  # bundles, which are extracted by unzip. Reject absolute/parent paths.
  tar -tzf "$1" > "$TMP/entries"
  if awk '/^\// || /(^|\/)\.\.($|\/)/ { bad=1 } END { exit !bad }' "$TMP/entries"; then fail 'unsafe archive path'; fi
  tar -tvzf "$1" > "$TMP/types"
  if awk 'substr($1, 1, 1) !~ /^[-d]$/ { bad=1 } END { exit !bad }' "$TMP/types"; then fail 'archive contains links or special files'; fi
  tar -xzf "$1" -C "$2"
}
DATA_HOME=${XDG_DATA_HOME:-$HOME/.local/share}
case "$DATA_HOME" in /*) ;; *) fail 'XDG_DATA_HOME must be absolute';; esac
APP_HOME="$DATA_HOME/tool-logger"
BIN_DIR="$HOME/.local/bin"
for candidate in "$HOME/.local/bin" "$HOME/bin"; do
  case ":${PATH:-}:" in *":$candidate:"*) BIN_DIR=$candidate; break;; esac
done
mkdir -p "$BIN_DIR" "$APP_HOME/backups"
# Refuse concurrent installs, including updates to a running bundle path.
LOCK="$APP_HOME/install.lock"
mkdir "$LOCK" 2>/dev/null || fail "another install is active: $LOCK"
cleanup_locked() { cleanup; rmdir "$LOCK"; }
trap cleanup_locked EXIT
STAGED=$(mktemp -d "$APP_HOME/.install.XXXXXX")
CLI_NAME="tool-logger_${VERSION}_${OS}_${ARCH}"
download "$CLI_NAME.tar.gz"
mkdir "$STAGED/cli"
extract_tar "$TMP/$CLI_NAME.tar.gz" "$STAGED/cli"
CLI="$STAGED/cli/$CLI_NAME/tool-logger"
[ -f "$CLI" ] && [ ! -L "$CLI" ] || fail 'CLI archive has no regular tool-logger binary'
chmod 755 "$CLI"
"$CLI" --version || fail 'downloaded CLI cannot run'
if [ "$SELECTION" != none ]; then
  PLUGIN_NAME="tool-logger-plugins_${VERSION}"
  download "$PLUGIN_NAME.tar.gz"
  mkdir "$STAGED/bundle"
  extract_tar "$TMP/$PLUGIN_NAME.tar.gz" "$STAGED/bundle"
  [ -f "$STAGED/bundle/$PLUGIN_NAME/install.ts" ] || fail 'bundle has no install.ts'
fi
if [ "$MODE" = desktop ]; then
  DESKTOP_NAME="tool-logger-desktop_${VERSION}_${OS}_${ARCH}"
  mkdir "$STAGED/desktop"
  if [ "$OS" = linux ]; then
    download "$DESKTOP_NAME.tar.gz"
    extract_tar "$TMP/$DESKTOP_NAME.tar.gz" "$STAGED/desktop"
    [ -f "$STAGED/desktop/$DESKTOP_NAME/tool-logger-desktop" ] || fail 'desktop archive has no executable'
  else
    has unzip || fail 'unzip is required'
    download "$DESKTOP_NAME.zip"
    unzip -Z1 "$TMP/$DESKTOP_NAME.zip" > "$TMP/entries"
    if awk '/^\// || /(^|\/)\.\.($|\/)/ { bad=1 } END { exit !bad }' "$TMP/entries"; then fail 'unsafe zip path'; fi
    unzip -q "$TMP/$DESKTOP_NAME.zip" -d "$STAGED/desktop"
    [ -d "$STAGED/desktop/$DESKTOP_NAME/Tool Logger.app" ] || fail 'desktop archive has no Tool Logger.app'
    APPLICATION="$HOME/Applications/Tool Logger.app"
    if [ -e "$APPLICATION" ] || [ -L "$APPLICATION" ]; then
      [ -L "$APPLICATION" ] && [ "$(readlink "$APPLICATION")" = "$APP_HOME/desktop/Tool Logger.app" ] || fail "unrelated application already exists: $APPLICATION"
    fi
  fi
  [ "$(digest "$CLI")" = "$(digest "$STAGED/desktop/$DESKTOP_NAME/tool-logger")" ] || fail 'desktop companion CLI differs from CLI archive'
fi
# Save prior installed paths. No source config, identity, journal or trust file
# is removed or rewritten by the shell installer.
WAS_RUNNING=false
if [ -x "$BIN_DIR/tool-logger" ] && "$BIN_DIR/tool-logger" server status >/dev/null 2>&1; then
  "$BIN_DIR/tool-logger" server stop || fail 'could not stop the previous collector before update'
  WAS_RUNNING=true
fi
BACKUP=$(mktemp -d "$APP_HOME/backups/install.XXXXXX")
replace() {
  source=$1 target=$2 backup_name=$3
  if [ -e "$target" ] || [ -L "$target" ]; then mv "$target" "$BACKUP/$backup_name"; fi
  mv "$source" "$target"
}
if [ "$SELECTION" != none ]; then
  replace "$STAGED/bundle/$PLUGIN_NAME" "$APP_HOME/plugins" plugins
fi
if [ "$MODE" = desktop ]; then
  replace "$STAGED/desktop/$DESKTOP_NAME" "$APP_HOME/desktop" desktop
  if [ "$OS" = linux ]; then
    chmod 755 "$APP_HOME/desktop/tool-logger-desktop"
    ln -sf "$APP_HOME/desktop/tool-logger-desktop" "$BIN_DIR/tool-logger-desktop"
    mkdir -p "$DATA_HOME/applications"
    # Desktop entry Exec arguments have their own quoting, independent of sh.
    entry_exec=$(printf '%s' "$BIN_DIR/tool-logger" | sed 's/%/%%/g')
    # shellcheck disable=SC2016
    entry_exec=$(printf '%s' "$entry_exec" | sed 's/[\\"`$]/\\&/g' | sed 's/\\/\\\\/g')
    cat > "$STAGED/tool-logger.desktop" <<EOF
[Desktop Entry]
Type=Application
Name=Tool Logger
Exec="$entry_exec"
Terminal=false
Categories=Development;
X-Tool-Logger-Installer=1
EOF
    replace "$STAGED/tool-logger.desktop" "$DATA_HOME/applications/tool-logger.desktop" desktop-entry
  else
    # The CLI finds this companion symlink alongside itself. Keep the app and
    # its resource CLI together in the persistent installation directory.
    ln -sf "$APP_HOME/desktop/Tool Logger.app/Contents/MacOS/tool-logger-desktop" "$BIN_DIR/tool-logger-desktop"
    mkdir -p "$HOME/Applications"
    ln -sfn "$APP_HOME/desktop/Tool Logger.app" "$APPLICATION"
  fi
fi
cp "$CLI" "$BIN_DIR/.tool-logger.$$"
chmod 755 "$BIN_DIR/.tool-logger.$$"
replace "$BIN_DIR/.tool-logger.$$" "$BIN_DIR/tool-logger" cli
if [ "$SELECTION" != none ]; then
  "$BIN_DIR/tool-logger" plugins install "$SELECTION" --bundle "$APP_HOME/plugins" || fail "plugin setup failed; prior files retained at $BACKUP; rerun after resolving the error"
elif [ "$WAS_RUNNING" = true ]; then
  "$BIN_DIR/tool-logger" server start || fail "installed CLI but could not restart collection; prior files retained at $BACKUP"
fi
printf 'Installed tool-logger %s at %s\n' "$VERSION" "$BIN_DIR/tool-logger"
case ":${PATH:-}:" in *":$BIN_DIR:"*) ;; *) printf 'Add %s to PATH.\n' "$BIN_DIR";; esac
printf 'Previous installation retained at %s\n' "$BACKUP"
